func TestProviderRedirectNeverSendsAdminCredentialsToAnotherOrigin(t *testing.T) {
	const rawRedirectCredentials = "example-user:example-password@"
	const rawRedirectQuery = "?X-Amz-Signature=example-signature&token=example-token#example-fragment"
	var redirectedRequests atomic.Int32
	unapprovedServer := httptest.NewServer(http.HandlerFunc(func(writer http.ResponseWriter, request *http.Request) {
		redirectedRequests.Add(1)
		writer.WriteHeader(http.StatusOK)
	}))
	t.Cleanup(unapprovedServer.Close)

	var approvedRequests atomic.Int32
	var approvedAuthorization atomic.Value
	approvedServer := httptest.NewServer(http.HandlerFunc(func(writer http.ResponseWriter, request *http.Request) {
		approvedRequests.Add(1)
		approvedAuthorization.Store(request.Header.Get("Authorization"))
		redirectURL := strings.Replace(unapprovedServer.URL, "://", "://"+rawRedirectCredentials, 1) + "/capture" + rawRedirectQuery
		http.Redirect(writer, request, redirectURL, http.StatusTemporaryRedirect)
	}))
	t.Cleanup(approvedServer.Close)

	response := configureProviderWithBaseURL(t, approvedServer.URL, true)
	if response.Diagnostics.HasError() {
		t.Fatalf("approved origin failed configuration: %v", response.Diagnostics)
	}
	providerData, ok := response.ResourceData.(*openaiapi.ProviderData)
	if !ok {
		t.Fatalf("provider data has unexpected type %T", response.ResourceData)
	}
	client, ok := providerData.Client("admin")
	if !ok {
		t.Fatal("provider data is missing the configured credential audience")
	}

	_, err := client.Request(
		context.Background(), http.MethodGet, "/organization/projects", nil, nil, nil,
	)
	if err == nil || !strings.Contains(err.Error(), "redirect crosses the configured OpenAI API origin") {
		t.Fatalf("cross-origin redirect error = %v", err)
	}
	if strings.Contains(err.Error(), "http: read on closed response body") {
		t.Fatalf("cross-origin redirect error was replaced while buffering: %v", err)
	}
	for _, secret := range []string{
		"example-user",
		"example-password",
		"X-Amz-Signature",
		"example-signature",
		"example-token",
		"example-fragment",
	} {
		if strings.Contains(err.Error(), secret) {
			t.Fatalf("cross-origin redirect error exposed %q: %v", secret, err)
		}
	}
	if !strings.Contains(err.Error(), unapprovedServer.URL+"/capture") {
		t.Fatalf("cross-origin redirect error lost sanitized destination: %v", err)
	}
	if got := approvedRequests.Load(); got != 1 {
		t.Fatalf("approved redirect origin received %d requests, want 1", got)
	}
	if got := approvedAuthorization.Load(); got != "Bearer "+testAdminAPIKey {
		t.Fatalf("approved origin authorization = %v", got)
	}
	if got := redirectedRequests.Load(); got != 0 {
		t.Fatalf("unapproved redirect origin received %d authenticated requests", got)
	}
}

func TestProviderSameOriginRedirectPreservesAdminCredentials(t *testing.T) {
	var receivedAuthorization atomic.Value
	server := httptest.NewServer(http.HandlerFunc(func(writer http.ResponseWriter, request *http.Request) {
		if request.URL.Path == "/organization/projects" {
			http.Redirect(writer, request, "/approved", http.StatusTemporaryRedirect)
			return
		}
		receivedAuthorization.Store(request.Header.Get("Authorization"))
		writer.Header().Set("Content-Type", "application/json")
		_, _ = fmt.Fprint(writer, "{}")
	}))
	t.Cleanup(server.Close)

	response := configureProviderWithBaseURL(t, server.URL, true)
	if response.Diagnostics.HasError() {
		t.Fatalf("approved origin failed configuration: %v", response.Diagnostics)
	}
	providerData, ok := response.ResourceData.(*openaiapi.ProviderData)
	if !ok {
		t.Fatalf("provider data has unexpected type %T", response.ResourceData)
	}
	client, ok := providerData.Client("admin")
	if !ok {
		t.Fatal("provider data is missing the configured credential audience")
	}
	if err := client.Client.Get(context.Background(), "/organization/projects", nil, nil, option.WithMaxRetries(0)); err != nil {
		t.Fatalf("same-origin redirect failed: %v", err)
	}
	if got := receivedAuthorization.Load(); got != "Bearer "+testAdminAPIKey {
		t.Fatalf("same-origin redirect authorization = %v", got)
	}
}

